            <div class="float ps-cams" id="psCams" role="group" aria-label="Camera">${[["bird","Bird\u2019s eye"],["top","Top"],["bed","From bed"],["sofa","From sofa"],["door","From door"],["walk","Walk"],["window","To window"]].map(([t,n])=>`<button type="button" data-v="${t}">${n}</button>`).join("")}</div>
